  return { queued, postId };
}

export async function listPosts(prisma: PrismaClient, workspaceId: string) {
  return prisma.post.findMany({
    where: { workspaceId },
    include: POST_INCLUDE,
    orderBy: { createdAt: "desc" },
  });
}

